import{TRACKS,COLORS,generate,detectHits,AudioEngine,wav,validateProject,clamp}from'./engine.js';
const $=id=>document.getElementById(id),names=['Intro','Verse','Hook','Outro'];let project=generate({idea:'Late-night drive, atmospheric keys and deep 808s',seed:2026}),pattern=1,bar=0,ctx,engine,playing=false,timer,stepIndex=0,nextTime=0,queue=[],songStep=0,history=[],recording=false,stream,recorder,chunks=[],recordTimer,captured=[],analyser,source,exporting=false;
try{const saved=JSON.parse(localStorage.getItem('pocket-project'));if(validateProject(saved))project=saved;}catch{}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function save(){try{localStorage.setItem('pocket-project',JSON.stringify(project));$('save-status').textContent='Saved on this device';}catch{$('save-status').textContent='Download project to save';}}
function checkpoint(){history.push(JSON.stringify(project));if(history.length>20)history.shift();}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function sync(){ $('project-name').value=project.name;$('bpm').value=project.bpm;$('swing').value=project.swing;$('swing-out').textContent=project.swing+'%';$('idea').value=project.idea||'';$('style').value=project.style||'nocturnal';$('key').value=project.key||0;render();}
function render(){renderGrid();renderSections();$('patterns').replaceChildren(...names.map((name,i)=>{const b=document.createElement('button');b.textContent=name;b.className=i===pattern?'active':'';b.onclick=()=>{stop();pattern=i;bar=0;render();};return b;}));$('bars').replaceChildren(...[0,1,2,3].map(i=>{const b=document.createElement('button');b.textContent='0'+(i+1);b.className=i===bar?'active':'';b.setAttribute('aria-label','Edit bar '+(i+1));b.onclick=()=>{bar=i;renderGrid();render();};return b;}));}
function renderGrid(){const grid=$('grid');grid.replaceChildren();const nums=document.createElement('div');nums.className='track-row numbers';nums.append(document.createElement('span'));for(let i=0;i<16;i++){const s=document.createElement('span');s.textContent=i%4===0?String(i/4+1):'·';nums.append(s);}grid.append(nums);TRACKS.forEach((name,tr)=>{const row=document.createElement('div');row.className='track-row';row.style.setProperty('--track',COLORS[tr]);const label=document.createElement('div');label.className='track-label';const top=document.createElement('div');top.className='track-top';const title=document.createElement('button');title.className='track-name';title.textContent=name;title.onclick=()=>preview(tr);const mute=document.createElement('button');mute.className='mute'+(project.mutes[tr]?' active':'');mute.textContent=project.mutes[tr]?'OFF':'M';mute.setAttribute('aria-label','Mute '+name);mute.setAttribute('aria-pressed',project.mutes[tr]);mute.onclick=()=>{checkpoint();project.mutes[tr]=!project.mutes[tr];if(engine)engine.bus[tr].gain.setTargetAtTime(project.mutes[tr]?0:project.volumes[tr],ctx.currentTime,.01);save();renderGrid();};top.append(title,mute);const volume=document.createElement('input');volume.type='range';volume.min=0;volume.max=100;volume.value=project.volumes[tr]*100;volume.setAttribute('aria-label',name+' volume');volume.oninput=()=>{project.volumes[tr]=Number(volume.value)/100;if(engine)engine.bus[tr].gain.setTargetAtTime(project.mutes[tr]?0:project.volumes[tr],ctx.currentTime,.01);save();};label.append(top,volume);row.append(label);for(let i=0;i<16;i++){const s=bar*16+i,n=project.patterns[pattern][tr][s],b=document.createElement('button');b.className='step'+(n?' on':'');b.dataset.step=s;b.setAttribute('aria-label',name+', bar '+(bar+1)+', step '+(i+1)+(n?', on':''));b.setAttribute('aria-pressed',!!n);if(n)b.style.opacity=.5+n.vel*.5;b.onclick=()=>{checkpoint();project.patterns[pattern][tr][s]=n?null:{vel:Number($('velocity').value),note:tr===5?24+(project.key||0):60+(project.key||0),len:tr>=5?2:1};if(!n&&!playing)preview(tr,project.patterns[pattern][tr][s]);save();renderGrid();};row.append(b);}grid.append(row);});}
function renderSections(){$('sections').replaceChildren(...project.arrangement.map((sec,i)=>{const el=document.createElement('div');el.className='song-section';el.dataset.section=i;const sel=document.createElement('select');sel.setAttribute('aria-label','Section '+(i+1)+' pattern');names.forEach((n,j)=>sel.add(new Option(n,j)));sel.value=sec.pattern;sel.onchange=()=>{checkpoint();stop();sec.pattern=Number(sel.value);save();renderSections();};const line=document.createElement('label'),num=document.createElement('input');num.type='number';num.min=1;num.max=32;num.value=sec.bars;num.setAttribute('aria-label','Section '+(i+1)+' bars');num.onchange=()=>{checkpoint();stop();sec.bars=clamp(Math.round(Number(num.value)||4),1,32);save();renderSections();};const del=document.createElement('button');del.textContent='×';del.setAttribute('aria-label','Remove section '+(i+1));del.onclick=()=>{if(project.arrangement.length===1)return toast('Keep at least one section.');checkpoint();stop();project.arrangement.splice(i,1);save();renderSections();};line.append(num,document.createTextNode('bars'),del);el.append(sel,line);return el;}));const bars=project.arrangement.reduce((s,a)=>s+a.bars,0),sec=bars*4*60/project.bpm;$('duration').textContent=`${bars} bars · ${Math.floor(sec/60)}:${String(Math.round(sec%60)).padStart(2,'0')} at ${project.bpm} BPM`;}
async function ready(){if(!ctx)ctx=new(window.AudioContext||window.webkitAudioContext)();if(ctx.state!=='running')await ctx.resume();}
async function preview(tr,n){try{await ready();const temp=new AudioEngine(ctx,project);temp.hit(tr,n||{vel:.8,note:tr===5?24+(project.key||0):60+(project.key||0),len:1},ctx.currentTime,60/project.bpm/4);setTimeout(()=>{temp.stop();temp.master.disconnect();temp.delay.disconnect();},2000);}catch{toast('Audio could not start. Try the play button again.');}}
function location(s){let offset=0;for(let i=0;i<project.arrangement.length;i++){const section=project.arrangement[i];if(s<offset+section.bars*16)return{pattern:section.pattern,step:(s-offset)%64,section:i};offset+=section.bars*16;}return location(s%offset);}
async function play(){if(recording)return toast('Finish your recording first.');if(playing)return stop(false);try{await ready();engine=new AudioEngine(ctx,project);playing=true;nextTime=ctx.currentTime+.07;$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','Pause beat');timer=setInterval(schedule,25);schedule();}catch{toast('This browser could not start audio.');}}
function schedule(){const step=60/project.bpm/4;while(nextTime<ctx.currentTime+.13){const song=$('song-mode').checked,pos=song?location(songStep):{pattern,step:stepIndex,section:-1},swing=pos.step%2?step*project.swing/100:0;engine.schedule(pos.pattern,pos.step,nextTime+swing,step);queue.push({...pos,time:nextTime+swing});nextTime+=step;stepIndex=(stepIndex+1)%64;songStep=(songStep+1)%(project.arrangement.reduce((sum,a)=>sum+a.bars,0)*16);}}
function stop(reset=true){playing=false;clearInterval(timer);queue=[];if(engine){const old=engine;old.stop();setTimeout(()=>{old.master.disconnect();old.delay.disconnect();},250);engine=null;}$('play').textContent='▶';$('play').setAttribute('aria-label','Play beat');document.querySelectorAll('.current,.playing').forEach(el=>el.classList.remove('current','playing'));if(reset){stepIndex=0;songStep=0;$('position').textContent='01';}}
function animate(){if(playing&&ctx){let current;while(queue.length&&queue[0].time<=ctx.currentTime)current=queue.shift();if(current){$('position').textContent=String(current.step+1).padStart(2,'0');if(pattern!==current.pattern||bar!==Math.floor(current.step/16)){pattern=current.pattern;bar=Math.floor(current.step/16);render();}document.querySelectorAll('.current,.playing').forEach(el=>el.classList.remove('current','playing'));document.querySelectorAll(`[data-step="${current.step}"]`).forEach(el=>el.classList.add('current'));document.querySelector(`[data-section="${current.section}"]`)?.classList.add('playing');}}drawWave();requestAnimationFrame(animate);}
function drawWave(){const canvas=$('wave'),g=canvas.getContext('2d');g.clearRect(0,0,canvas.width,canvas.height);g.strokeStyle=recording?'#ed9a86':'#83986c';g.lineWidth=2;g.beginPath();if(recording&&analyser){const data=new Uint8Array(analyser.fftSize);analyser.getByteTimeDomainData(data);for(let i=0;i<data.length;i++){const x=i/data.length*canvas.width,y=data[i]/255*canvas.height;i?g.lineTo(x,y):g.moveTo(x,y);}}else{for(let x=0;x<canvas.width;x+=5){const h=5+Math.sin(x*.037)**8*20;g.moveTo(x,55-h);g.lineTo(x,55+h);}}g.stroke();}
async function startRecord(){if(recording){recorder.stop();return;}stop();if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return toast('Microphone recording needs a supported browser on HTTPS.');try{await ready();stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});source=ctx.createMediaStreamSource(stream);analyser=ctx.createAnalyser();analyser.fftSize=512;source.connect(analyser);chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=finishRecord;recorder.start();recording=true;$('record').textContent='■ Finish';$('record').classList.add('recording');$('capture-status').textContent='Listening… First hit becomes beat one. Keep a steady tempo.';$('capture-review').hidden=true;recordTimer=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},Math.min(30000,64*60/project.bpm/4*1000+700));}catch(e){cleanupRecord();toast(e.name==='NotAllowedError'?'Microphone permission was denied. Allow it in browser settings.':'Microphone unavailable. Check your input device.');}}
function cleanupRecord(){recording=false;clearTimeout(recordTimer);stream?.getTracks().forEach(t=>t.stop());source?.disconnect();analyser=null;$('record').textContent='● Record';$('record').classList.remove('recording');}
async function finishRecord(){cleanupRecord();$('capture-status').textContent='Finding your rhythm…';try{const blob=new Blob(chunks,{type:recorder.mimeType}),buffer=await ctx.decodeAudioData(await blob.arrayBuffer());captured=detectHits(buffer.getChannelData(0),buffer.sampleRate,project.bpm,$('capture-mode').value,Number($('sensitivity').value)/100);$('capture-status').textContent=captured.length?'Review, then apply to the selected pattern.':'No clear hits found. Try louder taps in a quiet room.';$('hit-count').textContent=`${captured.length} hits detected · ${captured.filter(h=>h.track===0).length} kick / ${captured.filter(h=>h.track===1).length} snare / ${captured.filter(h=>h.track===2).length} hat`;$('capture-review').hidden=!captured.length;}catch{$('capture-status').textContent='This recording format could not be decoded. Try Safari, Chrome, or Edge.';}}
$('apply-hits').onclick=()=>{checkpoint();stop();for(const tr of [0,1,2])project.patterns[pattern][tr].fill(null);for(const h of captured)project.patterns[pattern][h.track][h.step]={vel:h.vel,note:60,len:1};$('capture-review').hidden=true;bar=0;save();render();toast('Your rhythm is ready to edit.');};$('discard-hits').onclick=()=>{$('capture-review').hidden=true;captured=[];};$('record').onclick=startRecord;
$('play').onclick=play;$('stop').onclick=()=>stop();$('song-mode').onchange=()=>stop();$('generate').onclick=()=>{if(recording)return toast('Finish your recording first.');checkpoint();stop();project=generate({idea:$('idea').value,style:$('style').value,energy:Number($('energy').value),density:Number($('density').value),key:Number($('key').value),seed:crypto.getRandomValues(new Uint32Array(1))[0]});pattern=1;bar=0;save();sync();toast('Fresh beat created. Press play to hear it.');};
for(const id of ['energy','density'])$(id).oninput=()=>$(id+'-out').textContent=$(id).value+'%';document.querySelectorAll('[data-idea]').forEach(b=>b.onclick=()=>{$('idea').value=b.dataset.idea;});$('bpm').onchange=()=>{stop();checkpoint();project.bpm=clamp(Math.round(Number($('bpm').value)||92),55,180);save();sync();};$('swing').oninput=()=>{project.swing=Number($('swing').value);$('swing-out').textContent=project.swing+'%';save();};$('project-name').onchange=()=>{project.name=$('project-name').value.trim()||'Untitled beat';save();};$('undo').onclick=()=>{if(!history.length)return toast('Nothing to undo yet.');stop();project=JSON.parse(history.pop());save();sync();toast('Last change undone.');};let taps=[];$('tap-tempo').onclick=()=>{const now=performance.now();if(now-(taps.at(-1)||0)>2000)taps=[];taps.push(now);taps=taps.slice(-6);if(taps.length>=3){stop();project.bpm=clamp(Math.round(60000/((now-taps[0])/(taps.length-1))),55,180);save();sync();}else toast('Keep tapping a steady quarter-note pulse.');};
$('save').onclick=()=>download(new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),'pocket-project.json');$('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error();const p=JSON.parse(await file.text());if(!validateProject(p))throw Error();checkpoint();stop();project=p;pattern=1;bar=0;save();sync();toast('Project loaded.');}catch{toast('This is not a valid Pocket project file.');}e.target.value='';};$('add-section').onclick=()=>{if(project.arrangement.length>=24)return toast('Maximum 24 sections.');checkpoint();stop();project.arrangement.push({pattern:1,bars:8});save();renderSections();};
TRACKS.forEach((name,i)=>{const b=document.createElement('button');b.style.setProperty('--track',COLORS[i]);b.textContent=name;const s=document.createElement('span');s.textContent='ASDFGHJK'[i];b.append(s);b.onpointerdown=e=>{e.preventDefault();preview(i);};b.onclick=e=>{if(e.detail===0)preview(i);};$('pads').append(b);$('export-track').add(new Option(name+' stem',String(i)));});
$('export').onclick=async()=>{if(exporting)return;exporting=true;stop();$('export').disabled=true;$('export').textContent='Rendering…';try{await new Promise(r=>setTimeout(r,60));const song=$('export-song').checked,copy=structuredClone(project),selected=$('export-track').value;if(selected!=='all')copy.mutes=TRACKS.map((_,i)=>i!==Number(selected));const step=60/copy.bpm/4,total=song?copy.arrangement.reduce((sum,a)=>sum+a.bars,0)*16:64,seconds=total*step+2;if(seconds>600)throw Error('Please shorten the arrangement to under 10 minutes.');const offline=new OfflineAudioContext(2,Math.ceil(seconds*44100),44100),audio=new AudioEngine(offline,copy);for(let s=0;s<total;s++){const pos=song?location(s):{pattern,step:s};audio.schedule(pos.pattern,pos.step,s*step+(pos.step%2?step*copy.swing/100:0),step);}audio.master.gain.setValueAtTime(.72,total*step);audio.master.gain.linearRampToValueAtTime(0,seconds-.1);const result=await offline.startRendering();download(wav(result),`${project.name.replace(/[^a-z0-9 _-]/gi,'').slice(0,45)||'Pocket'}${selected==='all'?'':'-'+TRACKS[Number(selected)]}.wav`);toast('WAV ready. Your browser will save the audio file.');}catch(e){toast(e.message||'Export failed. Try exporting a four-bar loop.');}finally{exporting=false;$('export').disabled=false;$('export').textContent='↓ Export WAV';}};
$('help').onclick=()=>$('guide').showModal();$('close-guide').onclick=()=>$('guide').close();document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('guide').open||e.repeat)return;if(e.code==='Space'){e.preventDefault();play();}const tr='asdfghjk'.indexOf(e.key.toLowerCase());if(tr>=0)preview(tr);});document.addEventListener('visibilitychange',()=>{if(document.hidden){stop(false);if(recording&&recorder.state==='recording')recorder.stop();}});sync();save();animate();
